using System;
using System.Collections.Generic;
using Framework.AI.Core;
using Framework.AI.Scheduling;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Actions;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.Stage;
using UnityEngine;

namespace Game.AI.Controllers
{
    /// <summary>
    /// 敵個体のAIと移動処理を管理する。
    /// </summary>
    /// <remarks>
    /// AIの思考更新はAgentUpdateManagerが担当する。
    /// フレーム単位の移動更新は本クラスが担当する。
    /// </remarks>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(GridMovementController))]
    public sealed class MazeEnemyController : MonoBehaviour
    {
        [Header("敵AI設定")]

        [SerializeField]
        [Tooltip("敵の性格と能力を定義するプロファイル。")]
        private MazeEnemyProfile profile;

        [SerializeField]
        [Tooltip("AIの思考更新間隔。単位は秒。")]
        [Min(0.01f)]
        private float thinkInterval = 0.2f;

        [Header("コンポーネント")]

        [SerializeField]
        [Tooltip("敵のグリッド移動コントローラー。")]
        private GridMovementController movement;

        [Header("デバッグ設定")]

        [SerializeField]
        [Tooltip("行動切り替え時にログを出力する。")]
        private bool logActionChanges = false;

        [SerializeField]
        [Tooltip("Sceneビューに移動経路を表示する。")]
        private bool drawDebugPath = true;

        [Header("実行時情報・確認専用")]

        [SerializeField]
        [Tooltip("敵AIが初期化されているか。")]
        private bool initialized;

        [SerializeField]
        [Tooltip("現在実行している行動。")]
        private MazeEnemyActionType currentAction;

        [SerializeField]
        [Tooltip("現在のセル座標。")]
        private Vector2Int currentCell;

        [SerializeField]
        [Tooltip("目的地が設定されているか。")]
        private bool hasDestination;

        [SerializeField]
        [Tooltip("現在の行動目的地。")]
        private Vector2Int destination;

        [SerializeField]
        [Tooltip("現在の移動速度。")]
        private float currentMoveSpeed;

        [SerializeField]
        [Tooltip("プレイヤーを視認しているか。")]
        private bool playerVisible;

        [SerializeField]
        [Tooltip("記憶している対象の数。")]
        private int rememberedTargetCount;

        [SerializeField]
        [Tooltip("AIの思考更新回数。")]
        private long tickCount;

        /// <summary>
        /// 接続先のステージ管理システム。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// AIの更新管理システム。
        /// </summary>
        private AgentUpdateManager updateManager;

        /// <summary>
        /// 個体専用のパラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// 敵AIの基本コンテキスト。
        /// </summary>
        private MazeEnemyContext enemyContext;

        /// <summary>
        /// 個体専用の自律型AI。
        /// </summary>
        private MazeEnemyAgent agent;

        /// <summary>
        /// 初期化済みであるか。
        /// </summary>
        public bool IsInitialized => initialized;

        /// <summary>
        /// 敵のプロファイル。
        /// </summary>
        public MazeEnemyProfile Profile => profile;

        /// <summary>
        /// 敵の移動コントローラー。
        /// </summary>
        public GridMovementController Movement => movement;

        /// <summary>
        /// 敵個体の自律型AI。
        /// </summary>
        public MazeEnemyAgent Agent => agent;

        /// <summary>
        /// 敵個体のパラメーターセット。
        /// </summary>
        public ParameterSet<MazeEnemyParameter> Parameters =>
            parameters;

        /// <summary>
        /// 敵個体の基本コンテキスト。
        /// </summary>
        public MazeEnemyContext EnemyContext =>
            enemyContext;

        /// <summary>
        /// 現在の行動。
        /// </summary>
        public MazeEnemyActionType CurrentAction =>
            agent != null
                ? agent.CurrentAction
                : MazeEnemyActionType.None;

        /// <summary>
        /// 敵が現在行動可能であるか。
        /// </summary>
        public bool CanAct =>
            initialized &&
            isActiveAndEnabled &&
            stageManager != null &&
            stageManager.IsPlaying &&
            agent != null &&
            agent.CanThink;

        /// <summary>
        /// 自身のコンポーネントを取得する。
        /// </summary>
        private void Awake()
        {
            CacheComponents();
        }

        /// <summary>
        /// 必要なコンポーネントを取得する。
        /// </summary>
        private void CacheComponents()
        {
            if (movement == null)
            {
                movement =
                    GetComponent<GridMovementController>();
            }

            if (movement != null)
            {
                // 移動処理の二重更新を防止する。
                movement.AutoUpdate = false;
            }
        }

        /// <summary>
        /// 敵個体を初期化する。
        /// </summary>
        /// <param name="newStageManager">
        /// 接続先のステージ管理システム
        /// </param>
        /// <param name="newUpdateManager">
        /// AI更新管理システム
        /// </param>
        /// <param name="spawnPosition">
        /// 敵の初期セル座標
        /// </param>
        /// <param name="targetProvider">
        /// 認識対象候補の取得処理
        /// </param>
        /// <param name="overrideProfile">
        /// 個体に適用する任意のプロファイル
        /// </param>
        /// <returns>初期化に成功した場合はtrue</returns>
        public bool Initialize(
            MazeStageManager newStageManager,
            AgentUpdateManager newUpdateManager,
            Vector2Int spawnPosition,
            Func<IReadOnlyList<MazeEnemyTargetSnapshot>>
                targetProvider,
            MazeEnemyProfile overrideProfile = null)
        {
            CacheComponents();

            // 初期化前に必要な依存関係を確認する。
            if (newStageManager == null ||
                newUpdateManager == null ||
                targetProvider == null ||
                movement == null ||
                !newStageManager.HasStage ||
                newStageManager.CoordinateConverter == null ||
                !newStageManager.IsWalkable(spawnPosition) ||
                float.IsNaN(thinkInterval) ||
                float.IsInfinity(thinkInterval) ||
                thinkInterval <= 0f)
            {
                return false;
            }

            Release();

            stageManager = newStageManager;
            updateManager = newUpdateManager;

            try
            {
                if (overrideProfile != null)
                {
                    profile = overrideProfile;
                }

                // プロファイル未設定時は標準値を使用する。
                parameters = profile != null
                    ? profile.CreateParameterSet()
                    : MazeEnemyParameterCatalog
                        .CreateParameterSet();

                // スポナーによって設定されたZ座標を維持する。
                Vector3 center =
                    stageManager.CoordinateConverter
                        .GetCellCenterWorld(spawnPosition);

                float zOffset =
                    transform.position.z - center.z;

                movement.Initialize(
                    stageManager.CoordinateConverter,
                    stageManager.IsWalkable,
                    spawnPosition,
                    zOffset);

                movement.MoveSpeed =
                    parameters.GetValue(
                        MazeEnemyParameter.MoveSpeed);

                string agentName = profile != null
                    ? profile.DisplayName
                    : gameObject.name;

                if (string.IsNullOrWhiteSpace(agentName))
                {
                    agentName = gameObject.name;
                }

                var agentContext =
                    new AgentContext<MazeEnemyParameter>(
                        agentName,
                        parameters);

                enemyContext =
                    new MazeEnemyContext(
                        agentContext,
                        stageManager,
                        movement,
                        spawnPosition);

                agent =
                    new MazeEnemyAgent(
                        enemyContext,
                        targetProvider);

                if (!agent.Initialize(agentContext))
                {
                    throw new InvalidOperationException(
                        "敵Agentの初期化に失敗しました。");
                }

                agent.ActionController.ActionStarted +=
                    HandleActionStarted;

                agent.ActionController.ActionEnded +=
                    HandleActionEnded;

                stageManager.StateChanged +=
                    HandleStageStateChanged;

                if (!updateManager.TryRegister(
                        agent, thinkInterval))
                {
                    throw new InvalidOperationException(
                        "Agentの更新登録に失敗しました。");
                }

                initialized = true;

                SynchronizeStageState();
                RefreshDebugInformation();

                return true;
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                Release();

                return false;
            }
        }

        /// <summary>
        /// ステージ状態の変化を処理する。
        /// </summary>
        /// <param name="previous">変更前の状態</param>
        /// <param name="current">変更後の状態</param>
        private void HandleStageStateChanged(
            MazeStageState previous,
            MazeStageState current)
        {
            SynchronizeStageState();
        }

        /// <summary>
        /// ステージ状態と敵AIの状態を同期する。
        /// </summary>
        public void SynchronizeStageState()
        {
            if (!initialized ||
                agent == null ||
                stageManager == null)
            {
                return;
            }

            if (!isActiveAndEnabled)
            {
                PauseAgent();

                return;
            }

            switch (stageManager.State)
            {
                case MazeStageState.Playing:

                    if (agent.IsPaused)
                    {
                        agent.Resume();
                    }
                    else if (!agent.IsActive)
                    {
                        agent.Activate();
                    }

                    // 再開時は早めに思考処理を実行する。
                    if (updateManager != null)
                    {
                        updateManager.RequestUpdate(agent);
                    }

                    break;

                case MazeStageState.Paused:

                    PauseAgent();

                    break;

                default:

                    // 準備中・クリア・失敗などでは停止する。
                    if (agent.IsActive || agent.IsPaused)
                    {
                        agent.Deactivate();
                    }

                    movement.StopImmediately();
                    movement.Pause();

                    break;
            }
        }

        /// <summary>
        /// AIと移動処理を一時停止する。
        /// </summary>
        private void PauseAgent()
        {
            if (agent != null && agent.IsActive)
            {
                agent.Pause();
            }

            if (movement != null)
            {
                movement.Pause();
            }
        }

        /// <summary>
        /// フレーム単位の移動処理を実行する。
        /// </summary>
        private void Update()
        {
            if (CanAct)
            {
                movement.Tick(Time.deltaTime);
            }
        }

        /// <summary>
        /// フレーム終了時に確認用情報を更新する。
        /// </summary>
        private void LateUpdate()
        {
            if (initialized)
            {
                RefreshDebugInformation();
            }
        }

        /// <summary>
        /// Inspectorの確認用情報を更新する。
        /// </summary>
        private void RefreshDebugInformation()
        {
            if (agent == null || movement == null)
            {
                return;
            }

            currentAction = agent.CurrentAction;
            currentCell = movement.CurrentCell;
            currentMoveSpeed = movement.MoveSpeed;
            tickCount = agent.TickCount;

            hasDestination =
                agent.TryGetCurrentDestination(
                    out destination);

            playerVisible =
                agent.Perception != null &&
                agent.Perception.TryGetBestObservation(
                    MazeEnemyTargetType.Player,
                    out var observation) &&
                observation.IsVisible;

            rememberedTargetCount =
                agent.Perception != null
                    ? agent.Perception.RememberedCount
                    : 0;
        }

        /// <summary>
        /// 行動開始時の確認ログを出力する。
        /// </summary>
        /// <param name="action">開始した行動</param>
        private void HandleActionStarted(
            MazeEnemyActionType action)
        {
            if (logActionChanges)
            {
                Debug.Log(
                    $"【敵AI】{gameObject.name} " +
                    $"行動開始：{action}",
                    this);
            }
        }

        /// <summary>
        /// 行動終了時の確認ログを出力する。
        /// </summary>
        /// <param name="action">終了した行動</param>
        /// <param name="reason">終了理由</param>
        private void HandleActionEnded(
            MazeEnemyActionType action,
            Framework.AI.Actions.AgentActionExitReason reason)
        {
            if (logActionChanges)
            {
                Debug.Log(
                    $"【敵AI】{gameObject.name} " +
                    $"行動終了：{action} / {reason}",
                    this);
            }
        }

        /// <summary>
        /// オブジェクト有効化時に状態を同期する。
        /// </summary>
        private void OnEnable()
        {
            SynchronizeStageState();
        }

        /// <summary>
        /// オブジェクト無効化時にAIを停止する。
        /// </summary>
        private void OnDisable()
        {
            if (initialized)
            {
                PauseAgent();
            }
        }

        /// <summary>
        /// 敵個体が所有する資源を解放する。
        /// </summary>
        public void Release()
        {
            initialized = false;

            if (stageManager != null)
            {
                stageManager.StateChanged -=
                    HandleStageStateChanged;
            }

            if (agent != null)
            {
                if (updateManager != null)
                {
                    updateManager.TryUnregister(agent);
                }

                if (agent.ActionController != null)
                {
                    agent.ActionController.ActionStarted -=
                        HandleActionStarted;

                    agent.ActionController.ActionEnded -=
                        HandleActionEnded;
                }

                agent.Dispose();
                agent = null;
            }

            enemyContext?.Dispose();
            enemyContext = null;

            parameters?.Dispose();
            parameters = null;

            if (movement != null &&
                movement.IsInitialized)
            {
                movement.StopImmediately();
                movement.Pause();
            }

            stageManager = null;
            updateManager = null;

            currentAction = MazeEnemyActionType.None;
            currentCell = default;
            destination = default;
            hasDestination = false;
            currentMoveSpeed = 0f;
            playerVisible = false;
            rememberedTargetCount = 0;
            tickCount = 0;
        }

        /// <summary>
        /// オブジェクト破棄時に資源を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Release();
        }

        /// <summary>
        /// Sceneビューに現在の移動経路を描画する。
        /// </summary>
        private void OnDrawGizmosSelected()
        {
            if (!drawDebugPath ||
                !Application.isPlaying ||
                !initialized ||
                agent == null ||
                agent.ActionContext == null ||
                stageManager == null)
            {
                return;
            }

            var converter =
                stageManager.CoordinateConverter;

            if (converter == null)
            {
                return;
            }

            var follower =
                agent.ActionContext.PathFollower;

            if (!follower.HasPath)
            {
                return;
            }

            var path = follower.Path;

            switch (agent.CurrentAction)
            {
                case MazeEnemyActionType.Chase:
                    Gizmos.color = Color.red;
                    break;

                case MazeEnemyActionType.Intercept:
                    Gizmos.color = Color.magenta;
                    break;

                case MazeEnemyActionType.Escape:
                    Gizmos.color = Color.cyan;
                    break;

                case MazeEnemyActionType.ReturnToTerritory:
                    Gizmos.color = Color.yellow;
                    break;

                default:
                    Gizmos.color = Color.green;
                    break;
            }

            // タイルマップより手前に経路を表示する。
            Vector3 offset =
                new Vector3(0f, 0f, -0.3f);

            Vector3 previous = transform.position;

            int startIndex = Mathf.Max(
                0, follower.CurrentPathIndex);

            for (int i = startIndex; i < path.Count; i++)
            {
                Vector3 point =
                    converter.GetCellCenterWorld(path[i]) +
                    offset;

                Gizmos.DrawLine(previous, point);
                Gizmos.DrawSphere(point, 0.055f);

                previous = point;
            }

            if (agent.TryGetCurrentDestination(
                    out Vector2Int target))
            {
                Vector3 targetWorld =
                    converter.GetCellCenterWorld(target) +
                    offset;

                Gizmos.DrawWireSphere(
                    targetWorld, 0.25f);
            }
        }
    }
}
